import type { FC } from 'react';

import { BasicContainer, DataStateHandler } from 'components';
import type { ChartLegendItem } from 'components';

import { PhiLineBarChartsGrid, TotalPhiCard } from '../../components';
import type {
  PhiOvertimeChartData,
  PhiOverviewViewState,
  TotalPhiCardData,
} from '../../types';
import {
  PHI_SECTION_SPACING,
  StyledPhiOvertimeCardHeader,
  StyledPhiOvertimeChartsGrid,
  StyledPhiOvertimeSubtitle,
  StyledPhiSectionInnerCard,
  StyledPhiSectionOuterBody,
} from './Overview.styles';

const SKELETON_PROPS = {
  height: '320px',
  width: '100%',
  length: 1,
  borderRadius: 'none' as const,
};

const SECTION_LAYOUT = {
  border: 'small' as const,
  shadow: 'small' as const,
  bodyPadding: false,
  headerPadding: 'none' as const,
  borderRadius: 'large' as const,
  background: '#F9F9F9',
  bodyStyle: {
    boxSizing: 'border-box' as const,
    padding: PHI_SECTION_SPACING,
    gap: PHI_SECTION_SPACING,
  },
};

export function resolveOverviewTestId(
  dataTestId: string | undefined,
  suffix: string,
  fallback?: string,
): string | undefined {
  if (dataTestId) {
    return `${dataTestId}-${suffix}`;
  }

  return fallback;
}

type SectionStateMessage = {
  title: string;
  description: string;
};

type TotalPhiOverviewSectionProps = {
  title: string;
  dataTestId?: string;
  view: PhiOverviewViewState;
  data: TotalPhiCardData | null;
  stateMessage?: SectionStateMessage;
};

export const TotalPhiOverviewSection: FC<TotalPhiOverviewSectionProps> = ({
  title,
  dataTestId,
  view,
  data,
  stateMessage,
}) => (
  <BasicContainer
    header={{ title, titleSize: 'H1' }}
    layout={SECTION_LAYOUT}
    fullWidth
    dataTestId={resolveOverviewTestId(
      dataTestId,
      'total-phi-section',
      'total-phi-section',
    )}
  >
    <StyledPhiSectionOuterBody
      data-testid={resolveOverviewTestId(
        dataTestId,
        'total-phi-outer-body',
        'total-phi-outer-body',
      )}
    >
      <DataStateHandler
        loading={view === 'loading'}
        error={view === 'error'}
        empty={view === 'empty' || !data}
        dataTestId={resolveOverviewTestId(dataTestId, 'total-phi-state')}
        message={stateMessage}
        skeletonProps={SKELETON_PROPS}
      >
        {view === 'ready' && data ? (
          <TotalPhiCard
            data={data}
            dataTestId={resolveOverviewTestId(
              dataTestId,
              'total-phi-card',
              'total-phi-card',
            )}
          />
        ) : null}
      </DataStateHandler>
    </StyledPhiSectionOuterBody>
  </BasicContainer>
);

type PhiPerformanceOverviewSectionProps = {
  title: string;
  overtimeSubtitle: string;
  dataTestId?: string;
  view: PhiOverviewViewState;
  overtime?: PhiOvertimeChartData;
  stateMessage?: SectionStateMessage;
  chartLegendItems: ChartLegendItem[];
};

export const PhiPerformanceOverviewSection: FC<
  PhiPerformanceOverviewSectionProps
> = ({
  title,
  overtimeSubtitle,
  dataTestId,
  view,
  overtime,
  stateMessage,
  chartLegendItems,
}) => (
  <BasicContainer
    header={{ title, titleSize: 'H1' }}
    layout={SECTION_LAYOUT}
    fullWidth
    dataTestId={resolveOverviewTestId(
      dataTestId,
      'phi-performance-section',
      'phi-performance-section',
    )}
  >
    <StyledPhiSectionOuterBody
      data-testid={resolveOverviewTestId(
        dataTestId,
        'phi-performance-outer-body',
        'phi-performance-outer-body',
      )}
    >
      <StyledPhiSectionInnerCard
        data-testid={resolveOverviewTestId(
          dataTestId,
          'phi-overtime-inner-card',
          'phi-overtime-inner-card',
        )}
      >
        <StyledPhiOvertimeCardHeader
          data-testid={resolveOverviewTestId(
            dataTestId,
            'phi-overtime-card-header',
            'phi-overtime-card-header',
          )}
        >
          <StyledPhiOvertimeSubtitle>
            {overtimeSubtitle}
          </StyledPhiOvertimeSubtitle>
        </StyledPhiOvertimeCardHeader>
        <DataStateHandler
          loading={view === 'loading'}
          error={view === 'error'}
          empty={view === 'empty' || !overtime || !!overtime.empty}
          dataTestId={resolveOverviewTestId(
            dataTestId,
            'phi-performance-state',
          )}
          message={stateMessage}
          skeletonProps={SKELETON_PROPS}
        >
          {view === 'ready' && overtime ? (
            <StyledPhiOvertimeChartsGrid
              data-testid={resolveOverviewTestId(
                dataTestId,
                'phi-overtime-charts-grid',
                'phi-overtime-charts-grid',
              )}
            >
              <PhiLineBarChartsGrid
                data={overtime}
                legendItems={chartLegendItems}
                dataTestId={resolveOverviewTestId(
                  dataTestId,
                  'phi-overtime',
                  'phi-overtime-charts',
                )}
              />
            </StyledPhiOvertimeChartsGrid>
          ) : null}
        </DataStateHandler>
      </StyledPhiSectionInnerCard>
    </StyledPhiSectionOuterBody>
  </BasicContainer>
);
